// patches/part27b_2a_httpx2.mjs  (run from repo root: node patches/part27b_2a_httpx2.mjs [--dry] [--no-lock] [--cutoff=YYYY-MM-DD])
// Replaces the dev dependency httpx with httpx2 (starlette.testclient now warns: "Using `httpx` with `starlette.testclient` is deprecated; install `httpx2` instead")
// and removes the filterwarnings line that hid that warning.
// Edited (6, by hunks): pyproject.toml, host/tests/test_locks_lint.py, justfile, docs/adr/0043.md, docs/PROGRESS.md (one bullet at the end), plus requirements-dev.lock (regenerated by uv, see below).
// Lock step: runs `uv pip compile` for requirements.lock and requirements-dev.lock with the SAME cut-off as the header of requirements-dev.lock (so nothing else moves), then checks:
//   requirements.lock has the same pins as before (if only the formatting differs, the old file is put back), the dev lock has httpx2 and the same pins as the runtime lock for everything in it.
// uv is looked for as `uv`, then `python -m uv`, `python3 -m uv`, `py -m uv`. Needs network (it asks PyPI for httpx2 and its hashes).
// If anything fails, EVERY file this script touched is put back as it was and the script exits 1. Safe to run twice (a hunk already there is skipped; if all hunks are there and the lock has httpx2, nothing happens).
// --dry writes nothing and runs nothing. --no-lock edits the text files only (the lock test will then fail until you regenerate the locks). --cutoff= overrides the cut-off read from the lock header.
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
const ROOT = process.cwd(), DRY = process.argv.includes('--dry'), NO_LOCK = process.argv.includes('--no-lock'), abs = (p) => path.join(ROOT, p);
const optArg = (k) => (process.argv.find((a) => a.startsWith(k + '=')) || '').slice(k.length + 1);
const LOCKS = ['requirements.lock', 'requirements-dev.lock'];

const EDITS = {
  'pyproject.toml': [
    ['    "httpx",        # not named in the design: fastapi.testclient needs it (P19)', '    "httpx2",       # not named in the design: fastapi.testclient needs it; replaces httpx, which starlette.testclient now warns is deprecated (P19)'],
    ['filterwarnings = ["ignore:Using `httpx` with `starlette.testclient`"]\n', ''],
  ],
  'host/tests/test_locks_lint.py': [
    ["{'pytest', 'hypothesis', 'httpx', 'pyyaml', 'ruff'}", "{'pytest', 'hypothesis', 'httpx2', 'pyyaml', 'ruff'}"],
  ],
  'justfile': [
    ['(runtime plus pytest, Hypothesis, httpx, pyyaml, ruff)', '(runtime plus pytest, Hypothesis, httpx2, pyyaml, ruff)'],
  ],
  'docs/adr/0043.md': [
    ['pytest, Hypothesis, httpx, pyyaml and ruff', 'pytest, Hypothesis, httpx2, pyyaml and ruff'],
  ],
};
const PROGRESS = { file: 'docs/PROGRESS.md', marker: 'Part 27b-2a done' };

const refuse = [], out = [], writes = [], backups = new Map();
const lf = (s) => s.replace(/\r\n/g, '\n');
const pins = (text) => Object.fromEntries([...text.matchAll(/^([A-Za-z0-9_.-]+)==(\S+) \\$/gm)].map((m) => [m[1].toLowerCase().replace(/_/g, '-'), m[2]]));

// ---- the cut-off: the one the dev lock was made with, so no other package moves
let cutoff = optArg('--cutoff');
if (!NO_LOCK) {
  for (const f of LOCKS) if (!fs.existsSync(abs(f))) refuse.push(`${f}: not found (run from the repo root)`);
  if (!cutoff && fs.existsSync(abs(LOCKS[1]))) {
    const m = /just lock (\d{4}-\d{2}-\d{2})/.exec(fs.readFileSync(abs(LOCKS[1]), 'utf8').split('\n').slice(0, 4).join('\n'));
    if (m) cutoff = m[1]; else refuse.push('requirements-dev.lock: no "just lock YYYY-MM-DD" in the first lines; pass --cutoff=YYYY-MM-DD');
  }
  if (cutoff && !/^\d{4}-\d{2}-\d{2}$/.test(cutoff)) refuse.push(`--cutoff must look like 2026-11-13, got ${cutoff}`);
}

// ---- the text edits, in memory
for (const [rel, hunks] of Object.entries(EDITS)) {
  if (!fs.existsSync(abs(rel))) { refuse.push(`${rel}: not found (run from the repo root)`); continue; }
  const raw = fs.readFileSync(abs(rel), 'utf8'), crlf = raw.includes('\r\n');
  let t = lf(raw), n = 0, bad = false;
  hunks.forEach(([oldT, newT], i) => {
    const c = t.split(oldT).length - 1;
    if (c === 1) { t = t.replace(oldT, () => newT); n++; }
    else if (c === 0 && (newT === '' || t.includes(newT))) { /* already there */ }
    else { refuse.push(`${rel}: hunk ${i + 1} does not match (${c} places); the file is not in the expected state`); bad = true; }
  });
  if (bad) continue;
  if (n) writes.push([rel, crlf ? t.replace(/\n/g, '\r\n') : t]);
  out.push(`${n ? 'edit   ' : 'already'} ${rel}${n ? ` (${n} hunk${n > 1 ? 's' : ''})` : ''}`);
}
{
  const rel = PROGRESS.file;
  if (!fs.existsSync(abs(rel))) refuse.push(`${rel}: not found`);
  else {
    const raw = fs.readFileSync(abs(rel), 'utf8'), crlf = raw.includes('\r\n'); let t = lf(raw);
    if (t.includes(PROGRESS.marker)) out.push(`already ${rel}`);
    else {
      const line = `- ${PROGRESS.marker} (not a numbered part; the warning from the P27b-2 test run): the dev dependency httpx is replaced by httpx2 in pyproject.toml (starlette.testclient warned that httpx is deprecated), requirements-dev.lock is regenerated by uv with the same cut-off (${NO_LOCK ? 'unchanged' : cutoff || 'see header'}) so no other pin moves, requirements.lock is unchanged, the filterwarnings line that hid the warning is removed, test_locks_lint.py names httpx2, justfile and ADR 0043 say httpx2; open for the operator: the full pytest run on Windows and the CI host job\n`;
      if (!t.endsWith('\n')) t += '\n';
      t += line; writes.push([rel, crlf ? t.replace(/\n/g, '\r\n') : t]); out.push(`edit   ${rel} (1 bullet appended)`);
    }
  }
}
if (!NO_LOCK && fs.existsSync(abs(LOCKS[1]))) {
  const dev = pins(fs.readFileSync(abs(LOCKS[1]), 'utf8'));
  out.push(`${dev.httpx2 ? 'already' : 'regen  '} requirements-dev.lock${dev.httpx2 ? ` (httpx2 ${dev.httpx2} is in it)` : ` (cut-off ${cutoff}; httpx ${dev.httpx || 'none'} is in it now)`}`);
}
console.log(out.join('\n'));
if (refuse.length) { console.error('\nNOTHING WRITTEN:\n' + refuse.join('\n')); process.exit(1); }
const needLock = !NO_LOCK && !pins(fs.readFileSync(abs(LOCKS[1]), 'utf8')).httpx2;
if (DRY) { console.log(`\n--dry: ${writes.length} file(s) would be edited${needLock ? ', then both lock files regenerated with uv' : ''}; nothing was written or run.`); process.exit(0); }
if (!writes.length && !needLock) { console.log('\nNothing to do.'); process.exit(0); }

// ---- write, remembering what was there, so that a failure puts everything back
for (const rel of [...writes.map((w) => w[0]), ...(needLock ? LOCKS : [])]) if (!backups.has(rel)) backups.set(rel, fs.readFileSync(abs(rel)));
const rollback = (why) => {
  for (const [rel, buf] of backups) fs.writeFileSync(abs(rel), buf);
  console.error(`\nFAILED: ${why}\nEvery file this script touched is back as it was (${backups.size} file(s)). Nothing to undo.`);
  process.exit(1);
};
for (const [rel, text] of writes) fs.writeFileSync(abs(rel), text, 'utf8');

if (needLock) {
  const base = ['pip', 'compile', 'pyproject.toml', '--python-version', '3.12', '--generate-hashes', '--exclude-newer', `${cutoff}T00:00:00Z`, '--custom-compile-command', `just lock ${cutoff}`];
  const candidates = [['uv'], ['python', '-m', 'uv'], ['python3', '-m', 'uv'], ['py', '-m', 'uv']];
  const run = (extra, outFile) => {
    for (const [cmd, ...pre] of candidates) {
      const r = spawnSync(cmd, [...pre, ...base, ...extra, '-o', outFile], { cwd: ROOT, stdio: 'inherit' });
      if (r.error && r.error.code === 'ENOENT') continue;
      if (r.error) rollback(`${cmd}: ${r.error.message}`);
      if (r.status !== 0) rollback(`uv pip compile for ${outFile} exited with ${r.status} (see its message above; if it cannot find httpx2, the release is newer than the cut-off ${cutoff} or the name is wrong)`);
      return;
    }
    rollback('uv was not found (tried: uv, python -m uv, python3 -m uv, py -m uv); run: python -m pip install uv');
  };
  console.log(`\nuv pip compile, cut-off ${cutoff} ...`);
  run([], LOCKS[0]);
  run(['--extra', 'dev'], LOCKS[1]);
  for (const f of LOCKS) { const t = fs.readFileSync(abs(f), 'utf8'); if (t.includes('\r')) fs.writeFileSync(abs(f), lf(t), 'utf8'); }   // LF only: the manifest hash and test_locks_lint need it
  const rtOld = pins(backups.get(LOCKS[0]).toString('utf8')), rtNew = pins(fs.readFileSync(abs(LOCKS[0]), 'utf8')), dev = pins(fs.readFileSync(abs(LOCKS[1]), 'utf8'));
  if (JSON.stringify(Object.entries(rtOld).sort()) !== JSON.stringify(Object.entries(rtNew).sort())) rollback('requirements.lock would have changed its pins; the runtime lock must not move for this swap');
  fs.writeFileSync(abs(LOCKS[0]), backups.get(LOCKS[0]));                                   // same pins: keep the old bytes, no churn from a different uv version
  if (!dev.httpx2) rollback('requirements-dev.lock has no httpx2 after uv ran');
  const off = Object.keys(rtNew).filter((k) => dev[k] !== rtNew[k]);
  if (off.length) rollback(`requirements-dev.lock disagrees with requirements.lock on: ${off.join(', ')}`);
  console.log(`\nrequirements-dev.lock: httpx2 ${dev.httpx2}${dev.httpx ? `, httpx ${dev.httpx} is still in it (something else needs it)` : ', httpx is gone'}; requirements.lock unchanged.`);
}
console.log(`\nwrote ${backups.size} file(s).\nNext: python -m pip install --require-hashes -r requirements-dev.lock, then python -m ruff check host tools and python -m pytest host/tests -q (the warning must not come back: the filter is gone), then git diff --stat`);
